def human_size(n):
    if n < 1024:
        return f'{n} B'
    units = ['KB', 'MB', 'GB']
    value = float(n)
    unit = None
    for unit in units:
        value /= 1024
        if value < 1024 or unit == units[-1]:
            break
    return f'{value:.1f} {unit}'

